public class AbstractCategoryItemRenderer_getLegendItems_TriageGen1Test {

    @Spy
    private AbstractCategoryItemRenderer renderer;

    private CategoryPlot plot;
    private CategoryDataset dataset;

    @Before
    public void setUp() {
        plot = mock(CategoryPlot.class);
        dataset = mock(CategoryDataset.class);
    }

    @Test
    public void testGetLegendItems_NullPlot() {
        renderer.setPlot(null);
        LegendItemCollection result = renderer.getLegendItems();
        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_NullDataset() {
        renderer.setPlot(plot);
        when(plot.getIndexOf(renderer)).thenReturn(0);
        when(plot.getDataset(0)).thenReturn(null);

        LegendItemCollection result = renderer.getLegendItems();
        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_AscendingOrder() {
        renderer.setPlot(plot);
        when(plot.getIndexOf(renderer)).thenReturn(0);
        when(plot.getDataset(0)).thenReturn(dataset);
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(2);

        // Mocking behavior for visibility and item retrieval
        // Series 0: visible, returns item
        // Series 1: not visible
        // Series 2: visible, returns item
        // Note: The loop in the source code is for (int i = -1; i < seriesCount; i++)
        // This covers i = -1, 0, 1.

        Mockito.doReturn(true).when(renderer).isSeriesVisibleInLegend(0);
        Mockito.doReturn(false).when(renderer).isSeriesVisibleInLegend(1);
        Mockito.doReturn(true).when(renderer).isSeriesVisibleInLegend(-1);

        LegendItem item0 = mock(LegendItem.class);
        LegendItem itemMinus1 = mock(LegendItem.class);

        Mockito.doReturn(item0).when(renderer).getLegendItem(0, 0);
        Mockito.doReturn(itemMinus1).when(renderer).getLegendItem(0, -1);
        Mockito.doReturn(null).when(renderer).getLegendItem(0, 1);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(2, result.size());
        // Based on loop: i=-1 (add), i=0 (add), i=1 (null, skip)
        assertTrue(result.contains(itemMinus1));
        assertTrue(result.contains(item0));
    }

    @Test
    public void testGetLegendItems_DescendingOrder() {
        renderer.setPlot(plot);
        when(plot.getIndexOf(renderer)).thenReturn(0);
        when(plot.getDataset(0)).thenReturn(dataset);
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.DESCENDING);
        when(dataset.getRowCount()).thenReturn(2);

        // Loop: for (int i = seriesCount - 1; i >= 0; i--) -> i=1, i=0
        Mockito.doReturn(true).when(renderer).isSeriesVisibleInLegend(1);
        Mockito.doReturn(true).when(renderer).isSeriesVisibleInLegend(0);

        LegendItem item1 = mock(LegendItem.class);
        LegendItem item0 = mock(LegendItem.class);

        Mockito.doReturn(item1).when(renderer).getLegendItem(0, 1);
        Mockito.doReturn(item0).when(renderer).getLegendItem(0, 0);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(2, result.size());
        // In descending, order should be item1 then item0
        // We check presence as LegendItemCollection is often treated as a list
        assertTrue(result.contains(item1));
        assertTrue(result.contains(item0));
    }

    @Test
    public void testGetLegendItems_WithNullLegendItems() {
        renderer.setPlot(plot);
        when(plot.getIndexOf(renderer)).thenReturn(0);
        when(plot.getDataset(0)).thenReturn(dataset);
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(1);

        // i = -1, 0
        Mockito.doReturn(true).when(renderer).isSeriesVisibleInLegend(-1);
        Mockito.doReturn(true).when(renderer).isSeriesVisibleInLegend(0);

        // Return null for one of them to test the null check
        Mockito.doReturn(null).when(renderer).getLegendItem(0, -1);
        Mockito.doReturn(mock(LegendItem.class)).when(renderer).getLegendItem(0, 0);

        LegendItemCollection result = renderer.getLegendItems();
        assertEquals(1, result.size());
    }
}

/**
 * Mocking LegendItem and LegendItemCollection if they are not easily accessible 
 * in the environment, but since this is a JFreeChart test, we assume they exist.
 */
interface LegendItem {}
class LegendItemCollection {
    private java.util.List<LegendItem> items = new java.util.ArrayList<>();
    public void add(LegendItem item) { items.add(item); }
    public int size() { return items.size(); }
    public boolean contains(LegendItem item) { return items.contains(item); }
}
